  export type SettledState<S> = Extract<S, { readonly position: 'terminal' | 'waiting' }>;
  export type IdleState<S> = Exclude<S, { readonly position: 'active' }>;
  export type OpenState<S> = Exclude<S, { readonly position: 'terminal' }>;

